const listEnvironments = `-- name: ListEnvironments :many
SELECT e.id, e.user_id, e.host_id, e.preset_id, e.name, e.generation, e.instance_id, e.desired, e.phase, e.observed_generation, e.reason, e.spec, e.cpu_millis, e.memory_bytes, e.storage_bytes, e.compute_reserved, e.request_key, e.request_hash, e.observed_at, e.created_at, e.updated_at, e.usage FROM environments e
CROSS JOIN LATERAL (
 SELECT CASE WHEN e.generation<>e.observed_generation THEN 'pending_' || e.desired ELSE e.phase END AS state,
 CASE WHEN e.desired='running' AND e.phase='running' AND e.generation=e.observed_generation
   AND (e.usage->>'at')::timestamptz >= now()-interval '90 seconds'
 THEN (e.usage->>'cpu_cores')::double precision END AS cpu_usage,
 CASE WHEN e.desired='running' AND e.phase='running' AND e.generation=e.observed_generation
   AND (e.usage->>'at')::timestamptz >= now()-interval '90 seconds'
 THEN (e.usage->>'memory_bytes')::bigint END AS memory_usage
) metrics
WHERE (e.user_id=$3::uuid OR $3::uuid IS NULL)
AND ($4::text='all'
 OR ($4::text='active' AND metrics.state<>'deleted')
 OR metrics.state=$4::text)
ORDER BY
 CASE WHEN $5::text='cpu_desc' THEN metrics.cpu_usage END DESC NULLS LAST,
 CASE WHEN $5::text='cpu_asc' THEN metrics.cpu_usage END ASC NULLS LAST,
 CASE WHEN $5::text='memory_desc' THEN metrics.memory_usage END DESC NULLS LAST,
 CASE WHEN $5::text='memory_asc' THEN metrics.memory_usage END ASC NULLS LAST,
 e.created_at DESC,e.id DESC LIMIT $1 OFFSET $2
`

