		var i Environment
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.HostID,
			&i.PresetID,
			&i.Name,
			&i.Generation,
			&i.InstanceID,
			&i.Desired,
			&i.Phase,
			&i.ObservedGeneration,
			&i.Reason,
			&i.Spec,
			&i.CpuMillis,
			&i.MemoryBytes,
			&i.StorageBytes,
			&i.ComputeReserved,
			&i.RequestKey,
			&i.RequestHash,
			&i.ObservedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Usage,
		); err != nil {
			return nil, err
		}
